def add_existing_unit_pack_history(apps, schema_editor):
    FinishedUnit = apps.get_model("workorders", "FinishedUnit")
    FinishedUnitHistory = apps.get_model("workorders", "FinishedUnitHistory")
    database = schema_editor.connection.alias
    units = FinishedUnit.objects.using(database).select_related("pack_confirmation")
    histories = []
    packed_at_by_unit = {}
    for unit in units.iterator():
        packed_at = unit.pack_confirmation.created_at
        histories.append(
            FinishedUnitHistory(
                unit_id=unit.pk,
                event_type="PACKED",
                to_status=unit.status,
                actor_id=unit.pack_confirmation.confirmed_by_id,
                note="Imported from the existing packing confirmation.",
                timestamp=packed_at,
            )
        )
        packed_at_by_unit[unit.pk] = packed_at
    FinishedUnitHistory.objects.using(database).bulk_create(histories)
    for unit_id, packed_at in packed_at_by_unit.items():
        FinishedUnitHistory.objects.using(database).filter(
            unit_id=unit_id,
            event_type="PACKED",
        ).update(timestamp=packed_at)


